                self._jobs[job_id] = {'state': 'queued'}

    def claim(self, worker, now, ttl):
        assert ttl > 0
        with self._lock:
            if ttl <= 0:
                return None
            # Reclaim eligible running jobs (expiry <= now), insertion order.
            if now >= 0:
                for job_id in list(self._running):
                    if self._running[job_id]['expiry'] <= now:
                        record = self._running.pop(job_id)
                        record['token'] = next(self._ids)
                        self._jobs[job_id] = {'state': 'queued',
