                                             'token': record['token']}
            # Then claim from the FIFO queue.
            if self._jobs:
                job_id, record = next(iter(self._jobs.items()))
                del self._jobs[job_id]
                token = next(self._ids)
                self._running[job_id] = {'worker': worker, 'token': token,
                                         'expiry': now + ttl}
                return {'job_id': job_id, 'worker': worker, 'token': token}
            return None

